{
 "summary": "The Lean theorem asserts that there is a ring A with a ℂ-algebra structure, finite-dimensional over ℂ, satisfying two things. First, its little finitistic dimension (the supremum of the projective dimensions of finitely generated left A-modules of finite projective dimension) equals ⊤. Second, for every m ≥ 1 there is a finitely generated left A-module N with 2m−2 ≤ pd N < ∞. This matches Theorem 1.1 faithfully. The main caveat is coverage only: the corollaries about the big finitistic dimension, injective generation, and Corollary 1.2 are not formalized. No faithfulness defect was found.",
 "glossary": [
  {"decl": "OAI.LittleFinitistic.littleFinitisticDimension", "line": 17, "plain": "fin.dim A = sup{ pd_A M : M a finitely generated left A-module, pd_A M < ∞ }, valued in WithBot ℕ∞. Mathlib's projectiveDimension is ⊥ for the zero module, and an empty supremum is ⊥.", "standard_concept": "little (left) finitistic dimension", "matches_standard": "yes", "note": "The ⊥ conventions for zero modules and the empty supremum are irrelevant here, because the theorem asserts the value ⊤."}
 ],
 "lean_claims": [
  {"theorem": "OAI.LittleFinitistic.Main.exists_counterexample", "line": 23, "plain": "There exist a type A, a ring structure on A and a ℂ-algebra structure on A such that: (1) A is finite-dimensional over ℂ; (2) littleFinitisticDimension A = ⊤; (3) for every natural number m > 0 there is a finitely generated left A-module N with (2m−2 : ℕ) ≤ pd N and pd N < ⊤."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.1", "plain": "There is a finite-dimensional unital complex algebra A such that, for every integer m ≥ 1, there is a finite-dimensional left A-module N_m with 2m−2 ≤ pd N_m < ∞. In particular fin.dim A = ∞."},
  {"ref": "Corollary 1.2", "plain": "There is a finite-dimensional complex algebra Λ with fin.dim Λ = Fin.dim Λ = ∞ and fin.dim Λ^op = Fin.dim Λ^op = 0."}
 ],
 "coverage": [
  {"paper_ref": "Theorem 1.1", "lean_theorem": "OAI.LittleFinitistic.Main.exists_counterexample", "relation": "equivalent", "why": "Over a finite-dimensional algebra, finitely generated modules are the same as finite-dimensional ones. The algebra is fixed before m is quantified, the bounds match, and fin.dim = ∞ is stated explicitly."},
  {"paper_ref": "Corollary 1.2", "lean_theorem": null, "relation": "not_formalized", "why": "Neither the left–right asymmetry, the big finitistic dimension, nor injective generation is stated in Lean."}
 ],
 "flags": [
  {"id": "F1", "category": "coverage", "severity": "low", "decl": "OAI.LittleFinitistic.Main.exists_counterexample", "line": 23, "paper_ref": "Corollary 1.2", "explanation": "Only Theorem 1.1 is formalized. The big-finitistic, injective-generation and asymmetry consequences are absent.", "polarity": "n/a", "probe_idea": null},
  {"id": "F2", "category": "other", "severity": "low", "decl": "OAI.LittleFinitistic.Main.exists_counterexample", "line": 26, "paper_ref": "Theorem 1.1", "explanation": "The paper speaks of finite-dimensional modules, while Lean uses Module.Finite A N. These are equivalent because A is finite-dimensional over ℂ via the algebra structure, so this is not a real discrepancy.", "polarity": "n/a", "probe_idea": "Prove: FiniteDimensional ℂ A → Module.Finite A N → FiniteDimensional ℂ N, using the restricted-scalars ℂ-structure."}
 ],
 "lint_verdicts": [
  {"line": 18, "rule": "junk-sInf", "verdict": "harmless", "why": "The iSup is in the complete lattice WithBot ℕ∞, where an empty supremum is ⊥. The theorem asserts the value ⊤, so this junk value cannot make the claim vacuous, and clause (3) independently forces unboundedness."},
  {"line": 17, "rule": "extended-arith", "verdict": "harmless", "why": "WithBot ℕ∞ is Mathlib's codomain for projectiveDimension. Its ⊤ is exactly 'infinite' and its ⊥ represents the zero module."},
  {"line": 27, "rule": "extended-arith", "verdict": "harmless", "why": "Since m > 0, the natural-number subtraction 2m−2 never truncates, and the cast into WithBot ℕ∞ is monotone, so the bound matches the paper's 2m−2."}
 ]
